(() => {
'use strict';
const C=window.PlannerCore, $=s=>document.querySelector(s), app=$('#app'), modalRoot=$('#modal-root');
const AUTH='imperium_auth_v2', CACHE='imperium_planner_cache_v1', PREF='imperium_planner_preferences_v1', FOCUS='imperium_planner_focus_v1';
const cfg=window.IMPERIUM_CONFIG||{}, base=cfg.DEFAULT_SUPABASE_URL, key=cfg.DEFAULT_SUPABASE_ANON_KEY;
const e=(v='')=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const read=(k,fallback=null)=>{try{return JSON.parse(localStorage.getItem(k))??fallback;}catch{return fallback;}};
const write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));}catch{toast('На устройстве мало места. Данные сохранены в облаке.');}};
const uuid=()=>crypto.randomUUID?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16);});
const S={auth:read(AUTH),owner:false,offline:false,tab:'today',date:C.day(),month:C.day().slice(0,7),filter:'active',query:'',project:null,tasks:[],projects:[],notes:[],sessions:[],lastSync:null,prefs:read(PREF,{theme:'light',defaultReminder:15}),focus:read(FOCUS,{minutes:25,remaining:1500,endsAt:null,taskId:null,sessionId:null}),refreshing:false};
const icons={today:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 5 2 2 5-5"/>',inbox:'<path d="M4 4h16l2 12v4H2v-4L4 4Z"/><path d="M2 15h6l2 3h4l2-3h6"/>',upcoming:'<rect x="3" y="4" width="18" height="17" rx="3"/><path d="M7 2v4m10-4v4M3 10h18m-12 5h6m-2-2 2 2-2 2"/>',calendar:'<rect x="3" y="4" width="18" height="17" rx="3"/><path d="M7 2v4m10-4v4M3 10h18m-13 4h1m6 0h1m-8 4h1m6 0h1"/>',projects:'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9H3V7Z"/>',notes:'<path d="M5 3h14v18H5zM8 8h8m-8 4h8m-8 4h5"/>',focus:'<circle cx="12" cy="13" r="8"/><path d="M12 9v4l3 2M9 2h6m4 3 2 2"/>',insights:'<path d="M4 20h17M7 16V9m6 7V4m6 12v-6"/>',settings:'<path d="M12 3 9 5H5v4l-2 3 2 3v4h4l3 2 3-2h4v-4l2-3-2-3V5h-4z"/><circle cx="12" cy="12" r="3"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5l-2 3Zm5 3h4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',play:'<path d="m8 5 11 7-11 7V5Z"/>',pause:'<path d="M8 5v14m8-14v14"/>',reset:'<path d="M4 10a8 8 0 1 1 1 8M4 4v6h6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',board:'<rect x="3" y="4" width="5" height="16" rx="1"/><rect x="10" y="4" width="5" height="10" rx="1"/><rect x="17" y="4" width="4" height="13" rx="1"/>',logout:'<path d="M10 4H4v16h6m-2-8h13m-4-4 4 4-4 4"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',repeat:'<path d="M4 8h15l-3-3m4 11H5l3 3M3 8v5m18 3v-5"/>',leaf:'<path d="M20 3C8 2 1 9 6 16c7 5 14-2 14-13ZM5 20 15 10"/>',edit:'<path d="m4 16 12-12 4 4L8 20H4v-4Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.today}</svg>`;
const navs=[['today','Мой день'],['inbox','Входящие'],['upcoming','Ближайшие дни'],['calendar','Календарь'],['board','Доска задач'],['notes','Заметки'],['focus','Фокус'],['insights','Обзор']];
const priorities={low:'Низкий',normal:'Обычный',high:'Высокий',urgent:'Срочно'};
const statuses={todo:'Запланировано',doing:'В работе',done:'Готово'};
const repeats={none:'Не повторять',daily:'Каждый день',weekdays:'По будням',weekly:'Каждую неделю',monthly:'Каждый месяц'};
const titleOf=()=>S.query?'Результаты поиска':S.tab==='project'?(project(S.project)?.name||'Проект'):S.tab==='projects'?'Мои проекты':S.tab==='settings'?'Настройки':navs.find(x=>x[0]===S.tab)?.[1]||'Мой день';
function project(id){return S.projects.find(p=>p.id===id);}
function dateLabel(d,opts={day:'numeric',month:'long'}){return d?new Intl.DateTimeFormat('ru-RU',{...opts,timeZone:'UTC'}).format(new Date(d+'T12:00:00Z')):'Без даты';}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),5000);}
function applyTheme(){const mode=S.prefs.theme||'light';document.documentElement.dataset.theme=mode==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):mode;}
applyTheme();matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',applyTheme);
let refreshingAuth=null;
async function refreshAuth(){if(!S.auth?.refresh_token)return;if(S.auth.expires_at&&S.auth.expires_at*1000>Date.now()+90000)return;if(refreshingAuth)return refreshingAuth;refreshingAuth=(async()=>{const r=await fetch(base+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:S.auth.refresh_token})});const j=await r.json();if(!r.ok){if(r.status===400||r.status===401){S.auth=null;S.owner=false;localStorage.removeItem(AUTH);renderLogin('Сессия закончилась. Войди ещё раз.');}throw Error('Не удалось продлить сессию.');}S.auth={...j,expires_at:j.expires_at||Math.floor(Date.now()/1000)+j.expires_in};write(AUTH,S.auth);})();try{await refreshingAuth;}finally{refreshingAuth=null;}}
async function api(path,{method='GET',body,headers={}}={}){await refreshAuth();const r=await fetch(base+path,{method,headers:{apikey:key,Authorization:'Bearer '+(S.auth?.access_token||''),'Content-Type':'application/json',...headers},body:body===undefined?undefined:JSON.stringify(body)});if(!r.ok){const x=await r.json().catch(()=>({}));if(r.status===401)throw Error('Сессия закончилась. Войди ещё раз.');if(r.status===403)throw Error('Доступ закрыт. Приложение доступно только владельцу.');if((x.message||'').includes('PLANNER_CONFLICT'))throw Error('Задача изменилась на другом устройстве. Обнови список и открой её снова.');throw Error(x.message||'Не удалось сохранить. Проверь соединение.');}return r.status===204?null:r.json();}
const rpc=(name,body={})=>api('/rest/v1/rpc/'+name,{method:'POST',body});
async function allRows(table,order='created_at.desc'){let rows=[],offset=0;while(true){const batch=await api(`/rest/v1/${table}?select=*&owner_id=eq.${S.auth.user.id}&order=${order}&limit=1000&offset=${offset}`);rows.push(...batch);if(batch.length<1000)return rows;offset+=1000;}}
async function load({quiet=false}={}){if(!S.auth||S.refreshing)return;S.refreshing=true;try{const access=await rpc('imperium_access_status');if(access!==true){S.owner=false;localStorage.removeItem(CACHE);try{window.AndroidBridge?.clearPlannerReminders?.();window.AndroidBridge?.clearAnnouncements?.();}catch{}renderBlocked();return;}S.owner=true;const values=await Promise.all([allRows('planner_tasks'),allRows('planner_projects'),allRows('planner_notes','updated_at.desc'),allRows('planner_focus_sessions','completed_at.desc')]);[S.tasks,S.projects,S.notes,S.sessions]=values;S.lastSync=new Date().toISOString();S.offline=false;write(CACHE,{owner:S.auth.user.id,tasks:S.tasks,projects:S.projects,notes:S.notes,sessions:S.sessions,lastSync:S.lastSync});if(!quiet||(!modalRoot.innerHTML&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)))render();scheduleReminders();checkUpdate();try{const pending=window.AndroidBridge?.pendingPlannerTask?.();if(pending&&S.tasks.some(t=>t.id===pending))taskModal(pending);}catch{}}catch(err){const cached=read(CACHE);if(!S.owner&&cached?.owner===S.auth?.user?.id){S.owner=true;S.tasks=cached.tasks||[];S.projects=cached.projects||[];S.notes=cached.notes||[];S.sessions=cached.sessions||[];S.lastSync=cached.lastSync;}S.offline=true;if(S.owner){if(!quiet)render();}else renderLogin('Не удалось подключиться. '+err.message);if(!quiet)toast('Нет синхронизации. Изменения доступны после подключения.');}finally{S.refreshing=false;}}
async function checkUpdate(){if(!window.AndroidBridge?.checkWebUpdate||S.offline||!S.owner)return;try{const rows=await api('/rest/v1/app_updates?select=version,version_name,package_url&active=eq.true&order=version.desc&limit=1');if(rows[0])window.AndroidBridge.checkWebUpdate(rows[0].version,rows[0].version_name,rows[0].package_url,S.auth.access_token,key);}catch{}}
async function login(email,password){const r=await fetch(base+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const j=await r.json();if(!r.ok)throw Error('Не удалось войти. Проверь email и пароль.');S.auth={...j,expires_at:j.expires_at||Math.floor(Date.now()/1000)+j.expires_in};write(AUTH,S.auth);await load();}
async function logout(){try{window.AndroidBridge?.clearPlannerReminders?.();window.AndroidBridge?.clearAnnouncements?.();await api('/auth/v1/logout',{method:'POST'});}catch{}localStorage.removeItem(AUTH);localStorage.removeItem(CACHE);localStorage.removeItem(FOCUS);S.auth=null;S.owner=false;S.tasks=[];S.notes=[];S.projects=[];S.focus={minutes:25,remaining:1500,endsAt:null};closeModal();renderLogin();}
function renderLogin(error=''){app.innerHTML=`<div class="auth-layout"><section class="auth-story"><div class="brand"><div class="brand-mark">i.</div><div><strong>IMPERIUM</strong><small>ЛИЧНОЕ ПРОСТРАНСТВО</small></div></div><div class="eyebrow">Меньше шума. Больше ясности.</div><h1>Твой день.<br>Твой ритм.</h1><p>Собери задачи в одном месте.<br>Оставь время для того, что действительно важно.</p></section><section class="auth-form"><div class="auth-card"><h2>С возвращением, Андрей</h2><p class="subtitle">Войди со своим прежним аккаунтом Империума.</p><form id="login-form"><label class="field">Email<input name="email" type="email" autocomplete="username" required placeholder="Твой email"></label><label class="field">Пароль<input name="password" type="password" autocomplete="current-password" required placeholder="Твой пароль"></label><div class="form-error" id="login-error">${e(error)}</div><button class="btn primary" type="submit">Войти в планировщик ${icon('arrow')}</button></form><div class="private-tag">${icon('lock')} Доступ только для владельца</div></div></section></div>`;$('#login-form').onsubmit=async ev=>{ev.preventDefault();const b=ev.target.querySelector('button'),f=new FormData(ev.target);b.disabled=true;$('#login-error').textContent='';try{await login(f.get('email').trim(),f.get('password'));}catch(err){$('#login-error').textContent=err.message;b.disabled=false;}};}
function renderBlocked(){app.innerHTML=`<div class="loading-screen"><div class="brand-mark">i.</div><h2>Личное пространство</h2><p>Доступ к Империуму закрыт владельцем.</p><button class="btn" data-action="logout">Выйти</button></div>`;}
function navButton(id,label,count){return `<button class="nav-btn ${S.tab===id?'active':''}" data-tab="${id}" aria-current="${S.tab===id?'page':'false'}">${icon(id)}<span>${label}</span>${count?`<b class="count">${count}</b>`:''}</button>`;}
function render(){if(!S.auth)return renderLogin();if(!S.owner)return renderBlocked();const active=S.tasks.filter(t=>t.status!=='done');app.innerHTML=`${S.offline?'<div class="offline-strip">Нет соединения · сохранённая копия · изменения временно недоступны</div>':''}<div class="layout"><aside class="sidebar"><div class="brand"><div class="brand-mark">i.</div><div><strong>IMPERIUM</strong><small>ТВОЁ ЛИЧНОЕ ПРОСТРАНСТВО</small></div></div><nav class="nav-group" aria-label="Основная навигация">${navs.map(([id,l])=>navButton(id,l,id==='today'?active.filter(t=>t.due_date===C.day()).length:id==='inbox'?active.filter(t=>!t.due_date).length:0)).join('')}</nav><div class="nav-caption"><span>Проекты</span><button data-action="new-project" aria-label="Создать проект">+</button></div><div class="project-nav">${S.projects.filter(p=>!p.archived).map(p=>`<button class="nav-btn ${S.tab==='project'&&S.project===p.id?'active':''}" data-project="${e(p.id)}"><i class="project-dot" style="background:${e(p.color)}"></i><span>${e(p.name)}</span></button>`).join('')}<button class="text-btn" data-tab="projects">Все проекты →</button></div><div class="sidebar-bottom">${navButton('settings','Настройки')}<div class="private-tag">${icon('lock')} Только для тебя</div><div class="profile"><div class="avatar">А</div><div><strong>Андрей</strong><small>Личный планировщик</small></div><button class="icon-btn" data-action="logout" aria-label="Выйти">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Личное пространство <span>/</span> ${e(titleOf())}</div><div class="mobile-brand"><div class="brand-mark">i.</div>IMPERIUM</div><div class="top-tools"><label class="search ${S.query?'expanded':''}">${icon('search')}<input id="search" type="search" value="${e(S.query)}" placeholder="Найти задачу…" aria-label="Поиск задач и заметок"><span class="kbd">/</span></label><button class="icon-btn ${active.some(t=>t.due_date&&t.due_date<C.day())?'dot-btn':''}" data-action="notifications" aria-label="Напоминания">${icon('bell')}</button><div class="avatar">А</div></div></header><div class="page-head"><div><div class="eyebrow">${S.tab==='today'?e(dateLabel(S.date,{weekday:'long',day:'numeric',month:'long'})):'IMPERIUM / PERSONAL'}</div><h1>${S.tab==='today'&&!S.query?(S.date===C.day()?'Хорошего дня, Андрей':e(dateLabel(S.date))):e(titleOf())}</h1><p class="subtitle">${pageSubtitle()}</p></div><div class="head-actions">${S.tab==='notes'?'<button class="btn primary" data-action="new-note">'+icon('plus')+'<span>Заметка</span></button>':S.tab==='projects'?'<button class="btn primary" data-action="new-project">'+icon('plus')+'<span>Проект</span></button>':'<button class="btn primary add-task" data-action="new-task">'+icon('plus')+'<span>Новая задача</span></button>'}</div></div>${S.query?searchPage():page()}<p class="sync-status" style="margin:24px 0 0">${S.lastSync?'Синхронизировано '+new Date(S.lastSync).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:C.TZ}):''} · Europe/Warsaw</p></main><nav class="mobile-nav" aria-label="Навигация">${[['today','День'],['inbox','Задачи'],['calendar','Календарь'],['notes','Заметки']].map(([id,l])=>`<button data-tab="${id}" class="${S.tab===id?'active':''}">${icon(id)}${l}</button>`).join('')}<button data-action="more">${icon('more')}Ещё</button></nav></div>`;bindSearch();updateFocusDisplay();}
function pageSubtitle(){const texts={today:'Всё важное перед глазами. Двигайся в своём темпе.',inbox:'Поймай мысль сейчас. Выбери время позже.',upcoming:'Ближайшие семь дней — без неприятных сюрпризов.',calendar:'Посмотри на месяц целиком. Оставь место для жизни.',board:'От идеи до результата, шаг за шагом.',projects:'Большие дела складываются из небольших шагов.',project:'Задачи, сроки и прогресс в одном месте.',notes:'Мысли, идеи и то, что хочется сохранить.',focus:'Одна задача. Немного тишины. Твоё внимание.',insights:'Замечай сделанное, а не только то, что впереди.',settings:'Настрой пространство под свой ритм.'};return e(S.query?'Задачи и заметки по твоему запросу.':texts[S.tab]||'');}
function page(){switch(S.tab){case 'today':return todayPage();case 'inbox':return taskPage(S.tasks.filter(t=>!t.due_date),'Без срока');case 'upcoming':return upcomingPage();case 'calendar':return calendarPage();case 'projects':return projectsPage();case 'project':return `<div class="section-heading"><span class="muted">${S.tasks.filter(t=>t.project_id===S.project&&t.status==='done').length} выполнено</span><button class="text-btn" data-action="edit-project" data-id="${e(S.project)}">Настроить проект</button></div>`+taskPage(S.tasks.filter(t=>t.project_id===S.project),'Задачи проекта');case 'board':return boardPage();case 'notes':return notesPage();case 'focus':return focusPage();case 'insights':return insightsPage();case 'settings':return settingsPage();default:return todayPage();}}
function empty(title,body,action='new-task',label='Добавить задачу'){return `<div class="empty">${icon('leaf')}<strong>${e(title)}</strong><p>${e(body)}</p>${action?`<button class="btn small soft" data-action="${action}">${icon('plus')}${e(label)}</button>`:''}</div>`;}
function filterButtons(){return `<div class="segmented" aria-label="Фильтр задач">${[['active','Активные'],['all','Все задачи'],['starred','Главное'],['done','Готово']].map(([id,l])=>`<button data-filter="${id}" class="${S.filter===id?'active':''}">${l}</button>`).join('')}</div>`;}
function filtered(tasks){return C.sortTasks(tasks.filter(t=>S.filter==='all'||S.filter==='starred'&&t.starred&&t.status!=='done'||S.filter==='done'&&t.status==='done'||S.filter==='active'&&t.status!=='done'));}
function taskCard(t,draggable=false){const p=project(t.project_id),over=t.due_date&&t.due_date<C.day()&&t.status!=='done',cl=Array.isArray(t.checklist)?t.checklist:[];return `<article class="task ${t.status==='done'?'done':''}" ${draggable?`draggable="true" data-drag="${e(t.id)}"`:''}><button class="check ${t.status==='done'?'checked':''}" data-action="complete" data-id="${e(t.id)}" aria-label="${t.status==='done'?'Вернуть в работу':'Выполнить'}: ${e(t.title)}">${t.status==='done'?icon('check'):''}</button><button class="task-main" data-action="edit-task" data-id="${e(t.id)}"><span class="task-title">${e(t.title)}</span><span class="task-meta">${t.due_date?`<span class="meta ${over?'overdue':''}">${icon('clock')}${t.due_time?e(t.due_time.slice(0,5))+' · ':''}${t.due_date===C.day()?'Сегодня':e(dateLabel(t.due_date,{day:'numeric',month:'short'}))}</span>`:''}${p?`<span class="meta"><i class="project-dot" style="width:5px;height:5px;background:${e(p.color)}"></i>${e(p.name)}</span>`:''}${t.priority==='high'||t.priority==='urgent'?`<span class="pill ${t.priority}">${priorities[t.priority]}</span>`:''}${t.status==='doing'?'<span class="pill">В работе</span>':''}${cl.length?`<span>${cl.filter(x=>x.done).length}/${cl.length} шагов</span>`:''}${t.repeat_rule!=='none'?`<span class="meta" title="${repeats[t.repeat_rule]}">${icon('repeat')}</span>`:''}${t.reminder_minutes!==null?'<span class="meta">'+icon('bell')+'</span>':''}</span></button><button class="star ${t.starred?'on':''}" data-action="star" data-id="${e(t.id)}" aria-label="${t.starred?'Убрать из главного':'Отметить главным'}">${t.starred?'★':'☆'}</button></article>`;}
function taskList(tasks){return tasks.length?`<div class="task-list">${tasks.map(t=>taskCard(t)).join('')}</div>`:empty('Здесь пока спокойно','Добавь первое дело — план начнёт складываться.');}
function quickAdd(){return `<form class="quick-add" id="quick-add">${icon('plus')}<input name="title" maxlength="300" placeholder="Быстро добавить задачу…" aria-label="Название новой задачи" required><button type="submit" class="text-btn">Enter ↵</button></form>`;}
function taskPage(tasks,title){return `<section><div class="section-heading"><h2>${e(title)}</h2><span class="muted">${tasks.filter(t=>t.status!=='done').length} осталось</span></div>${filterButtons()}${taskList(filtered(tasks))}${quickAdd()}</section>`;}
function todayPage(){const tasks=S.tasks.filter(t=>t.due_date===S.date),done=tasks.filter(t=>t.status==='done').length,remaining=tasks.length-done,minutes=tasks.filter(t=>t.status!=='done').reduce((a,t)=>a+t.duration_minutes,0),overdue=S.tasks.filter(t=>t.due_date&&t.due_date<S.date&&t.status!=='done');const planned=tasks.filter(t=>t.due_time&&t.status!=='done').sort((a,b)=>a.due_time.localeCompare(b.due_time));return `<div class="dashboard"><section><div class="hero"><div><div class="eyebrow">Место для главного</div><h2>${remaining?'Не всё сразу.<br>Одно важное дело.':'День начинается<br>с ясного плана.'}</h2><p>${remaining?`Сегодня у тебя ${remaining} ${plural(remaining,'задача','задачи','задач')}. Выбери главное и начни с небольшого шага.`:'Добавь задачи, расставь приоритеты.<br>Остальное пусть подождёт.'}</p></div><div class="hero-art" aria-hidden="true"><div class="hero-orbit"></div><svg viewBox="0 0 150 140" fill="none"><path d="M76 125C78 96 76 64 98 20" stroke="#6f8354" stroke-width="2"/><path d="M82 91C43 95 31 67 35 53c35-1 48 14 47 38Z" fill="#b4c68e"/><path d="M88 67c32 2 45-21 41-39-29 2-42 17-41 39Z" fill="#8da875"/><path d="M98 40C77 37 72 20 80 5c24 9 26 22 18 35Z" fill="#cedbb4"/><path d="M77 111c-24 5-43-10-44-25 25-4 42 5 44 25Z" fill="#8ca66a"/><ellipse cx="77" cy="130" rx="35" ry="4" fill="#cad7b3"/><path d="M80 88 43 62m46 2 31-25m-41 68L41 93" stroke="#718b51" stroke-width="1"/></svg></div></div><div class="metrics"><div class="metric"><div class="metric-top">${icon('today')}В плане</div><strong>${tasks.length}<small>на этот день</small></strong></div><div class="metric"><div class="metric-top">${icon('check')}Выполнено</div><strong>${done}<small>${tasks.length?Math.round(done/tasks.length*100):0}% плана</small></strong></div><div class="metric"><div class="metric-top">${icon('clock')}Загрузка</div><strong>${minutes>=60?(minutes/60).toFixed(1).replace('.',','):minutes}<small>${minutes>=60?'часа осталось':'минут осталось'}</small></strong></div></div><div class="section-heading"><h2>Задачи на день</h2><div><button class="icon-btn" data-action="day-prev" aria-label="Предыдущий день">${icon('left')}</button><button class="text-btn" data-action="go-today">Сегодня</button><button class="icon-btn" data-action="day-next" aria-label="Следующий день">${icon('right')}</button></div></div>${filterButtons()}${taskList(filtered(tasks))}${quickAdd()}${overdue.length?`<div class="date-group"><div class="section-heading"><h2>Осталось с прошлых дней <span class="badge">${overdue.length}</span></h2><button class="text-btn" data-action="carry-overdue">На сегодня →</button></div>${taskList(C.sortTasks(overdue).slice(0,5))}${overdue.length>5?'<button class="text-btn" data-tab="upcoming">Все просроченные →</button>':''}</div>`:''}</section><aside class="right-col"><div class="panel">${miniCalendar()}</div>${focusPanel()}<div class="panel timeline-panel"><div class="section-heading"><h2>Ритм дня</h2>${icon('clock')}</div>${planned.length?`<div class="timeline">${planned.map(t=>`<button class="timeline-item" data-action="edit-task" data-id="${e(t.id)}"><span class="timeline-time">${e(t.due_time.slice(0,5))}</span><span class="timeline-content"><strong>${e(t.title)}</strong><small>${t.duration_minutes} мин${project(t.project_id)?' · '+e(project(t.project_id).name):''}</small></span></button>`).join('')}</div>`:'<div class="empty compact"><p>Укажи время в задаче,<br>и здесь появится расписание.</p></div>'}</div></aside></div>`;}
function plural(n,a,b,c){return n%10===1&&n%100!==11?a:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?b:c;}
function monthDates(){const first=S.month+'-01',weekday=(new Date(first+'T12:00:00Z').getUTCDay()+6)%7,start=C.addDays(first,-weekday);return Array.from({length:42},(_,i)=>C.addDays(start,i));}
function calendarHeader(){return `<div class="calendar-header"><strong>${e(dateLabel(S.month+'-01',{month:'long',year:'numeric'}).replace(' г.',''))}</strong><div class="calendar-arrows"><button class="icon-btn" data-action="month-prev" aria-label="Предыдущий месяц">${icon('left')}</button><button class="icon-btn" data-action="month-next" aria-label="Следующий месяц">${icon('right')}</button></div></div>`;}
function miniCalendar(){return calendarHeader()+`<div class="calendar-grid">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=>`<span class="weekday">${d}</span>`).join('')}${monthDates().map(d=>`<button class="calendar-day ${d.slice(0,7)!==S.month?'outside':''} ${d===C.day()?'today':''} ${d===S.date?'selected':''} ${S.tasks.some(t=>t.due_date===d&&t.status!=='done')?'has-tasks':''}" data-date="${d}" aria-label="${e(dateLabel(d))}">${Number(d.slice(-2))}</button>`).join('')}</div>`;}
function calendarPage(){return `<section class="big-calendar">${calendarHeader()}<div class="calendar-grid">${['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'].map(d=>`<span class="weekday">${d.slice(0,2)}</span>`).join('')}${monthDates().map(d=>{const ts=C.sortTasks(S.tasks.filter(t=>t.due_date===d&&t.status!=='done'));return `<button class="big-day ${d.slice(0,7)!==S.month?'outside':''} ${d===S.date?'selected':''} ${d===C.day()?'today':''}" data-date="${d}" aria-label="${e(dateLabel(d))}, задач: ${ts.length}"><span class="day-number">${Number(d.slice(-2))}</span>${ts.slice(0,2).map(t=>`<span class="cal-task">${t.due_time?e(t.due_time.slice(0,5))+' ':''}${e(t.title)}</span>`).join('')}${ts.length>2?`<small>+${ts.length-2}</small>`:''}</button>`;}).join('')}</div></section>`;}
function upcomingPage(){const today=C.day(),overdue=C.sortTasks(S.tasks.filter(t=>t.due_date&&t.due_date<today&&t.status!=='done'));return `${overdue.length?`<section class="upcoming-group"><h3 class="upcoming-title overdue">Просроченные <span class="badge">${overdue.length}</span><button class="text-btn" data-action="carry-overdue">Перенести на сегодня</button></h3>${taskList(overdue)}</section>`:''}${Array.from({length:7},(_,i)=>C.addDays(today,i)).map(d=>{const ts=C.sortTasks(S.tasks.filter(t=>t.due_date===d&&t.status!=='done'));return `<section class="upcoming-group"><div class="section-heading"><h3 class="upcoming-title">${d===today?'Сегодня':d===C.addDays(today,1)?'Завтра':e(dateLabel(d,{weekday:'long'}))} <span class="muted">${e(dateLabel(d,{day:'numeric',month:'short'}))}</span></h3><button class="text-btn" data-action="task-for-date" data-id="${d}">+ Задача</button></div>${ts.length?taskList(ts):'<p class="subtitle">Свободное пространство в плане.</p>'}</section>`;}).join('')}`;}
function boardPage(){return `<div class="kanban">${Object.entries(statuses).map(([s,l])=>{const ts=C.sortTasks(S.tasks.filter(t=>t.status===s));return `<section class="kanban-column" data-drop-status="${s}"><h3>${l}<span class="badge">${ts.length}</span></h3>${ts.map(t=>taskCard(t,true)).join('')}${!ts.length?'<p class="subtitle">Перетащи задачу сюда или измени статус в её карточке.</p>':''}</section>`;}).join('')}</div>`;}
function projectsPage(){const ps=S.projects.filter(p=>!p.archived);return ps.length?`<div class="project-cards">${ps.map(p=>{const ts=S.tasks.filter(t=>t.project_id===p.id),done=ts.filter(t=>t.status==='done').length;return `<button class="project-card" data-project="${e(p.id)}"><i class="project-dot" style="background:${e(p.color)}"></i><h3>${e(p.name)}</h3><p>${ts.length-done} активных задач</p><div class="progress"><span style="width:${ts.length?done/ts.length*100:0}%"></span></div><small>${done} из ${ts.length} выполнено</small></button>`;}).join('')}</div>`:empty('Раздели дела по направлениям','Работа, личное, ремонт или большая идея — у каждого проекта своё место.','new-project','Создать проект');}
function noteCards(ns){return `<div class="notes-grid">${ns.sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.updated_at.localeCompare(a.updated_at)).map(n=>`<button class="note-card" data-action="edit-note" data-id="${e(n.id)}"><h3>${n.pinned?'✦ ':''}${e(n.title)}</h3><p>${e(n.body.slice(0,400))}</p><small>${e(dateLabel(C.day(new Date(n.updated_at)),{day:'numeric',month:'short'}))}</small></button>`).join('')}</div>`;}
function notesPage(){return S.notes.length?noteCards([...S.notes]):empty('Идеям нужно место','Сохрани мысль, список, черновик письма или план.','new-note','Создать заметку');}
function searchPage(){const ts=C.sortTasks(S.tasks.filter(t=>C.matches(t,S.query))),ns=S.notes.filter(n=>(n.title+' '+n.body).toLowerCase().includes(S.query.toLowerCase()));return `<div class="section-heading"><h2>Задачи · ${ts.length}</h2><button class="text-btn" data-action="clear-search">Сбросить поиск</button></div>${ts.length?taskList(ts):empty('Ничего не найдено','Попробуй другое слово.',null)}${ns.length?'<div class="section-heading" style="margin-top:28px"><h2>Заметки</h2></div>'+noteCards(ns):''}`;}
function focusPanel(){return `<div class="panel focus-panel"><div class="focus-ring"></div><div class="focus-label">${icon('focus')}Время сфокусироваться</div><div class="focus-time" data-focus-time>25:00</div><div class="focus-caption">${S.focus.taskId?e(S.tasks.find(t=>t.id===S.focus.taskId)?.title||'Одна задача за раз'):'Одна задача. Никакой суеты.'}</div><div class="focus-buttons"><button class="btn" data-action="focus-toggle" data-focus-toggle>${icon(S.focus.endsAt?'pause':'play')}${S.focus.endsAt?'Пауза':'Начать'}</button><button class="icon-btn" data-action="focus-reset" aria-label="Сбросить таймер">${icon('reset')}</button></div></div>`;}
function focusPage(){return `<div class="focus-big"><div class="eyebrow">Твоё время — ценно</div><h2>Сосредоточься на одном</h2><select id="focus-task" aria-label="Задача для фокуса"><option value="">Свободная сессия</option>${S.tasks.filter(t=>t.status!=='done').map(t=>`<option value="${e(t.id)}" ${t.id===S.focus.taskId?'selected':''}>${e(t.title)}</option>`).join('')}</select><div class="focus-time" data-focus-time>25:00</div><p class="focus-task-label">${S.offline?'Для сохранения сессии нужно соединение.':'После сессии сделай короткий перерыв.'}</p><div class="focus-buttons"><button class="btn primary" data-action="focus-toggle" data-focus-toggle>${icon(S.focus.endsAt?'pause':'play')}${S.focus.endsAt?'Пауза':'Начать фокус'}</button><button class="btn" data-action="focus-reset">${icon('reset')}Сбросить</button></div><div class="focus-presets">${[15,25,45,60].map(n=>`<button data-action="focus-preset" data-id="${n}">${n} мин</button>`).join('')}</div></div>`;}
function insightsPage(){const days=Array.from({length:7},(_,i)=>C.addDays(C.day(),i-6)),counts=days.map(d=>S.tasks.filter(t=>t.status==='done'&&t.completed_at&&C.day(new Date(t.completed_at))===d).length),sum=counts.reduce((a,b)=>a+b,0),focus=S.sessions.filter(s=>days.includes(C.day(new Date(s.completed_at)))).reduce((a,s)=>a+s.duration_minutes,0),total=S.tasks.filter(t=>t.status==='done').length,max=Math.max(1,...counts);return `<div class="metrics"><div class="metric"><div class="metric-top">${icon('check')}За неделю</div><strong>${sum}<small>задач выполнено</small></strong></div><div class="metric"><div class="metric-top">${icon('focus')}Концентрация</div><strong>${focus}<small>минут за неделю</small></strong></div><div class="metric"><div class="metric-top">${icon('projects')}За всё время</div><strong>${total}<small>завершённых задач</small></strong></div></div><div class="panel"><h2>Маленькие шаги. Видимый результат.</h2><p class="subtitle">Завершённые задачи за последние семь дней.</p><div class="weekly-chart">${days.map((d,i)=>`<div class="bar-col"><strong>${counts[i]}</strong><div class="bar" style="height:${counts[i]/max*120}px"></div><span>${e(dateLabel(d,{weekday:'short'}))}</span></div>`).join('')}</div></div><div style="margin-top:24px">${taskPage(S.tasks.filter(t=>t.status==='done'),'Последние завершённые')}</div>`;}
function settingsPage(){let native=false;try{native=typeof window.AndroidBridge?.schedulePlannerReminders==='function';}catch{}return `<div class="settings-grid"><section class="panel"><h2>Твоё пространство</h2><div class="settings-row"><div><strong>Оформление</strong><p>Светлая, тёмная или системная тема.</p></div><select id="theme-setting" aria-label="Тема">${[['light','Светлая'],['dark','Тёмная'],['system','Как в системе']].map(([v,l])=>`<option value="${v}" ${S.prefs.theme===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="settings-row"><div><strong>Напоминать заранее</strong><p>По умолчанию для задач с датой.</p></div><select id="default-reminder" aria-label="Напоминание по умолчанию">${[[0,'В момент'],[5,'За 5 мин'],[15,'За 15 мин'],[30,'За 30 мин'],[60,'За час']].map(([v,l])=>`<option value="${v}" ${Number(S.prefs.defaultReminder)===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="settings-row"><div><strong>Часовой пояс</strong><p>Europe/Warsaw · даты и время Польши.</p></div>${icon('clock')}</div></section><section class="panel"><h2>Напоминания</h2><p class="subtitle">${native?'Уведомления Android работают и при закрытом приложении. После изменения задач на другом устройстве открой приложение для обновления расписания.':'В этой версии уведомления работают, пока планировщик открыт. Для напоминаний при закрытом приложении установи Android 7.0.'}</p><div class="settings-row"><div><strong>Разрешить уведомления</strong><p>Система спросит разрешение.</p></div><button class="btn small" data-action="enable-notifications">Включить</button></div>${native?'<div class="settings-row"><div><strong>Точное время</strong><p>Без разрешения Android может задерживать сигнал.</p></div><button class="btn small" data-action="exact-alarms">Настроить</button></div>':'<div class="settings-row"><div><strong>Android 7.0</strong><p>Обновление поверх установленной версии.</p></div><button class="btn small" data-action="download-apk">Скачать APK</button></div>'}<div class="settings-row"><div><strong>Пробное уведомление</strong><p>Проверь звук и разрешения.</p></div><button class="btn small" data-action="test-reminder">Проверить</button></div></section><section class="panel"><h2>Данные</h2><div class="settings-row"><div><strong>Обновить данные</strong><p>Загрузить изменения с других устройств.</p></div><button class="btn small" data-action="refresh">Обновить</button></div><div class="settings-row"><div><strong>Резервная копия</strong><p>Задачи, проекты, заметки и статистика в JSON.</p></div><button class="btn small" data-action="export-json">Экспорт</button></div><div class="settings-row"><div><strong>Календарь</strong><p>Экспорт задач со сроками в файл .ics.</p></div><button class="btn small" data-action="export-ics">Экспорт</button></div></section><section class="panel"><h2>Личный доступ</h2><p class="subtitle">Планировщик и данные доступны только твоему аккаунту. Регистрация сотрудников закрыта.</p><div class="settings-row"><div><strong>Архив Империума</strong><p>Старые договоры, объекты и другие данные.</p></div><a class="btn small" href="legacy.html">Открыть</a></div><div class="settings-row"><div><strong>Аккаунт</strong><p>${e(S.auth.user.email||'Владелец')}</p></div><button class="btn small" data-action="logout">Выйти</button></div></section></div>`;}
function bindSearch(){const s=$('#search');if(!s)return;s.parentElement.onclick=()=>{s.parentElement.classList.add('expanded');s.focus();};s.oninput=()=>{S.query=s.value;clearTimeout(bindSearch.timer);bindSearch.timer=setTimeout(()=>{const pos=s.selectionStart;render();const n=$('#search');n.focus();try{n.setSelectionRange(pos,pos);}catch{}},250);};}
function showModal(content,wide=false){modalRoot.innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true">${content}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>modalRoot.querySelector('input,textarea,button')?.focus(),30);}
function closeModal(){modalRoot.innerHTML='';document.body.style.overflow='';}
function modalHead(title){return `<div class="modal-head"><h2>${e(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div>`;}
function taskModal(id=null,date=null){const old=S.tasks.find(t=>t.id===id);const defaultDate=date||(S.tab==='inbox'?null:S.tab==='today'?S.date:null);const t=old||{title:'',notes:'',due_date:defaultDate,due_time:null,duration_minutes:30,priority:'normal',status:'todo',repeat_rule:'none',reminder_minutes:defaultDate?(S.prefs.defaultReminder??15):null,starred:false,checklist:[],tags:[],project_id:S.tab==='project'?S.project:null};showModal(`${modalHead(old?'Детали задачи':'Новая задача')}<form id="task-form" data-id="${e(id||'')}"><div class="form-grid"><label class="field full">Название<input class="title-input" name="title" value="${e(t.title)}" maxlength="300" required placeholder="Что хочешь сделать?"></label><label class="field full">Заметки<textarea name="notes" maxlength="20000" placeholder="Детали, ссылки, мысли…">${e(t.notes)}</textarea></label><label class="field">Дата<input type="date" name="due_date" value="${e(t.due_date||'')}"></label><label class="field">Время · Польша<input type="time" name="due_time" value="${e((t.due_time||'').slice(0,5))}"></label><label class="field">Проект<select name="project_id"><option value="">Без проекта</option>${S.projects.filter(p=>!p.archived||p.id===t.project_id).map(p=>`<option value="${e(p.id)}" ${p.id===t.project_id?'selected':''}>${e(p.name)}</option>`).join('')}</select></label><label class="field">Приоритет<select name="priority">${Object.entries(priorities).map(([v,l])=>`<option value="${v}" ${v===t.priority?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Длительность, минут<input type="number" name="duration_minutes" min="5" max="1440" value="${t.duration_minutes}" required></label><label class="field">Статус<select name="status">${Object.entries(statuses).map(([v,l])=>`<option value="${v}" ${v===t.status?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Повтор<select name="repeat_rule">${Object.entries(repeats).map(([v,l])=>`<option value="${v}" ${v===t.repeat_rule?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Напоминание<select name="reminder_minutes">${[['','Без напоминания'],[0,'В назначенное время'],[5,'За 5 минут'],[15,'За 15 минут'],[30,'За 30 минут'],[60,'За час'],[1440,'За день']].map(([v,l])=>`<option value="${v}" ${String(v)===String(t.reminder_minutes??'')?'selected':''}>${l}</option>`).join('')}</select></label><label class="field full">Метки (через запятую)<input name="tags" value="${e((t.tags||[]).join(', '))}" placeholder="звонок, документы, личное"></label><div class="field full">Подзадачи<div class="checklist" id="checklist">${(t.checklist||[]).map(checkline).join('')}</div><button class="text-btn" type="button" data-action="add-check">+ Добавить шаг</button></div><label class="form-inline field full"><input type="checkbox" name="starred" ${t.starred?'checked':''}>Отметить как главное</label></div><p class="archive-hint" style="margin:12px 0 0">Если время не задано, напоминание привязано к 09:00. Повтор создаёт следующую задачу после выполнения.</p><div class="form-error" id="form-error"></div><div class="modal-actions"><div>${old?'<button type="button" class="btn small danger" data-action="delete-task" data-id="'+e(id)+'">'+icon('trash')+'</button><button type="button" class="btn small" data-action="duplicate-task" data-id="'+e(id)+'">Копия</button>':''}</div><div><button type="button" class="btn" data-action="close-modal">Отмена</button><button type="submit" class="btn primary">Сохранить</button></div></div></form>`);const dateInput=modalRoot.querySelector('[name=due_date]');dateInput.addEventListener('change',()=>{if(!old&&dateInput.value)modalRoot.querySelector('[name=reminder_minutes]').value=String(S.prefs.defaultReminder??15);});$('#task-form').onsubmit=ev=>saveTaskForm(ev,old);}
function checkline(x={id:uuid(),text:'',done:false}){return `<div class="checkline" data-check-id="${e(x.id)}"><input type="checkbox" ${x.done?'checked':''} aria-label="Шаг выполнен"><input type="text" value="${e(x.text)}" maxlength="300" placeholder="Следующий шаг"><button type="button" class="icon-btn" data-action="remove-check" aria-label="Удалить шаг">${icon('close')}</button></div>`;}
async function saveTaskForm(ev,old){ev.preventDefault();const f=new FormData(ev.target),button=ev.target.querySelector('[type=submit]');button.disabled=true;try{const t={title:String(f.get('title')).trim(),notes:String(f.get('notes')),due_date:f.get('due_date')||null,due_time:f.get('due_time')||null,project_id:f.get('project_id')||null,priority:f.get('priority'),duration_minutes:Number(f.get('duration_minutes')),status:f.get('status'),repeat_rule:f.get('repeat_rule'),reminder_minutes:f.get('reminder_minutes')===''?null:Number(f.get('reminder_minutes')),starred:f.has('starred'),tags:String(f.get('tags')).split(',').map(s=>s.trim()).filter(Boolean).slice(0,20),checklist:[...ev.target.querySelectorAll('.checkline')].map(x=>({id:x.dataset.checkId,text:x.querySelector('[type=text]').value.trim(),done:x.querySelector('[type=checkbox]').checked})).filter(x=>x.text)};C.validateTask(t);const complete=t.status==='done'&&old?.status!=='done';if(complete)t.status=old?.status||'todo';if(t.status!=='done')t.completed_at=null;const saved=old?await patchTask(old,t):await insertRow('planner_tasks',t);if(complete)await rpc('planner_complete_task',{p_id:saved.id,p_expected:saved.updated_at});closeModal();await load();toast(complete?'Задача выполнена. Хороший шаг.':'Задача сохранена');}catch(err){$('#form-error').textContent=err.message;}finally{button.disabled=false;}}
function requireOnline(){if(S.offline||!navigator.onLine)throw Error('Сейчас нет соединения. Дождись синхронизации и повтори.');}
async function insertRow(table,row){requireOnline();const rows=await api('/rest/v1/'+table,{method:'POST',body:{...row,owner_id:S.auth.user.id},headers:{Prefer:'return=representation'}});return rows[0];}
async function patchTask(t,patch){requireOnline();const rows=await api(`/rest/v1/planner_tasks?id=eq.${t.id}&updated_at=eq.${encodeURIComponent(t.updated_at)}`,{method:'PATCH',body:patch,headers:{Prefer:'return=representation'}});if(!rows?.length)throw Error('Задача изменилась на другом устройстве. Обнови список.');return rows[0];}
async function complete(id){const t=S.tasks.find(x=>x.id===id);if(!t)return;requireOnline();if(t.status==='done')await patchTask(t,{status:'todo',completed_at:null});else await rpc('planner_complete_task',{p_id:t.id,p_expected:t.updated_at});await load();toast(t.status==='done'?'Задача возвращена в план':'Готово. Ещё одно дело позади.');}
function projectModal(id=null){const p=project(id)||{name:'',color:'#8b9e70'};showModal(`${modalHead(id?'Настройки проекта':'Новый проект')}<form id="project-form"><div class="form-grid"><label class="field full">Название<input name="name" required maxlength="100" value="${e(p.name)}" placeholder="Например, Личное или TERIMEX"></label><label class="field full">Цвет<input type="color" name="color" value="${e(p.color)}" style="height:45px"></label></div><div class="form-error" id="form-error"></div><div class="modal-actions"><div>${id?`<button class="btn danger" type="button" data-action="archive-project" data-id="${e(id)}">В архив</button>`:''}</div><button type="submit" class="btn primary">Сохранить</button></div></form>`);$('#project-form').onsubmit=async ev=>{ev.preventDefault();const b=ev.target.querySelector('[type=submit]');b.disabled=true;try{requireOnline();const f=new FormData(ev.target),row={name:f.get('name').trim(),color:f.get('color')};if(id)await api('/rest/v1/planner_projects?id=eq.'+id,{method:'PATCH',body:row,headers:{Prefer:'return=representation'}});else await insertRow('planner_projects',row);closeModal();await load();toast('Проект сохранён');}catch(err){$('#form-error').textContent=err.message;b.disabled=false;}};}
function noteModal(id=null){const n=S.notes.find(n=>n.id===id)||{title:'',body:'',pinned:false};showModal(`${modalHead(id?'Заметка':'Новая заметка')}<form id="note-form"><div class="form-grid"><label class="field full">Название<input class="title-input" name="title" value="${e(n.title)}" required maxlength="200" placeholder="О чём эта заметка?"></label><label class="field full">Текст<textarea name="body" style="min-height:240px" maxlength="100000" placeholder="Мысли, ссылки, планы…">${e(n.body)}</textarea></label><label class="form-inline field full"><input name="pinned" type="checkbox" ${n.pinned?'checked':''}>Закрепить</label></div><div class="form-error" id="form-error"></div><div class="modal-actions"><div>${id?`<button type="button" class="btn danger" data-action="delete-note" data-id="${e(id)}">Удалить</button>`:''}</div><button type="submit" class="btn primary">Сохранить</button></div></form>`,true);$('#note-form').onsubmit=async ev=>{ev.preventDefault();const b=ev.target.querySelector('[type=submit]');b.disabled=true;try{requireOnline();const f=new FormData(ev.target),row={title:f.get('title').trim(),body:f.get('body'),pinned:f.has('pinned')};if(id){const rows=await api(`/rest/v1/planner_notes?id=eq.${id}&updated_at=eq.${encodeURIComponent(n.updated_at)}`,{method:'PATCH',body:row,headers:{Prefer:'return=representation'}});if(!rows?.length)throw Error('Заметка изменилась на другом устройстве. Обнови список.');}else await insertRow('planner_notes',row);closeModal();await load();toast('Заметка сохранена');}catch(err){$('#form-error').textContent=err.message;b.disabled=false;}};}
function confirmAction(title,body,action,id){showModal(`${modalHead(title)}<p class="subtitle">${e(body)}</p><div class="modal-actions"><button class="btn" data-action="close-modal">Отмена</button><button class="btn primary" data-action="${action}" data-id="${e(id)}">Подтвердить</button></div>`);}
async function deleteRow(table,id){requireOnline();await api('/rest/v1/'+table+'?id=eq.'+id,{method:'DELETE',headers:{Prefer:'return=representation'}});closeModal();await load();toast('Удалено');}
function focusRemaining(){return Math.max(0,S.focus.endsAt?Math.ceil((S.focus.endsAt-Date.now())/1000):Number(S.focus.remaining??S.focus.minutes*60));}
function updateFocusDisplay(){const n=focusRemaining(),text=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');document.querySelectorAll('[data-focus-time]').forEach(el=>el.textContent=text);if(S.focus.endsAt&&n===0&&!updateFocusDisplay.finishing)finishFocus();}
async function finishFocus(){updateFocusDisplay.finishing=true;const finished={id:S.focus.sessionId||uuid(),owner_id:S.auth?.user?.id,task_id:S.focus.taskId||null,duration_minutes:S.focus.minutes,completed_at:new Date().toISOString()};S.focus.endsAt=null;S.focus.remaining=S.focus.minutes*60;S.focus.pending=finished;write(FOCUS,S.focus);if(typeof window.AndroidBridge?.schedulePlannerReminders==='function')toast('Фокус завершён. Время короткого перерыва.');else notify('Фокус завершён','Хорошая работа. Время короткого перерыва.');await savePendingFocus();render();updateFocusDisplay.finishing=false;}
async function savePendingFocus(){if(!S.focus.pending||!S.owner||S.offline)return;try{await api('/rest/v1/planner_focus_sessions?on_conflict=id',{method:'POST',body:S.focus.pending,headers:{Prefer:'resolution=ignore-duplicates,return=representation'}});S.focus.pending=null;write(FOCUS,S.focus);await load({quiet:true});}catch{toast('Сессия завершена. Сохраним её после подключения.');}}
function toggleFocus(){if(S.focus.pending){toast('Сначала сохраним предыдущую сессию. Проверь соединение.');savePendingFocus();return;}if(S.focus.endsAt){S.focus.remaining=focusRemaining();S.focus.endsAt=null;}else{if(!S.focus.remaining)S.focus.remaining=S.focus.minutes*60;S.focus.endsAt=Date.now()+S.focus.remaining*1000;S.focus.sessionId=S.focus.sessionId||uuid();}write(FOCUS,S.focus);render();scheduleReminders();}
function resetFocus(minutes=S.focus.minutes||25){S.focus={...S.focus,minutes,remaining:minutes*60,endsAt:null,sessionId:uuid()};write(FOCUS,S.focus);render();scheduleReminders();}
function notify(title,body){toast(title+' · '+body);try{if(window.AndroidBridge?.notify){window.AndroidBridge.notify(title,body);return;}if('Notification'in window&&Notification.permission==='granted')new Notification(title,{body,icon:'icons/planner.svg'});}catch{} }
const reminded=new Set(read('imperium_planner_reminded',[]));let nativeSchedule='';
function scheduleReminders(){if(!S.owner)return;const items=S.tasks.filter(t=>t.status!=='done').map(t=>({id:t.id,title:t.title,body:(t.due_time?t.due_time.slice(0,5):'09:00')+' · '+(project(t.project_id)?.name||'IMPERIUM'),at:C.reminderAt(t)})).filter(x=>Number.isFinite(x.at)&&x.at>Date.now()-86400000).sort((a,b)=>a.at-b.at).slice(0,100);if(S.focus.endsAt)items.push({id:'focus-'+S.focus.sessionId,title:'Фокус завершён',body:'Время небольшого перерыва.',at:S.focus.endsAt});const data=JSON.stringify(items);if(data!==nativeSchedule){try{if(typeof window.AndroidBridge?.schedulePlannerReminders==='function'){window.AndroidBridge.schedulePlannerReminders(data);nativeSchedule=data;}}catch{}}}
function checkReminders(){if(!S.owner)return;const hasNative=typeof window.AndroidBridge?.schedulePlannerReminders==='function';for(const t of S.tasks){const at=C.reminderAt(t),token=t.id+':'+at;if(t.status!=='done'&&Number.isFinite(at)&&at<=Date.now()&&at>Date.now()-5*60000&&!reminded.has(token)){reminded.add(token);if(!hasNative)notify('Напоминание',t.title);}}if(reminded.size>500){const latest=[...reminded].slice(-250);reminded.clear();latest.forEach(x=>reminded.add(x));}write('imperium_planner_reminded',[...reminded]);}
function notificationsModal(){const ts=C.sortTasks(S.tasks.filter(t=>t.status!=='done'&&t.due_date&&t.due_date<=C.day()));showModal(`${modalHead('Напоминания')}<p class="subtitle" style="margin-bottom:18px">Сегодня и то, что осталось с предыдущих дней.</p>${ts.length?taskList(ts):empty('Всё спокойно','Срочных напоминаний сейчас нет.',null)}<div class="modal-actions"><button class="btn" data-action="enable-notifications">Разрешить уведомления</button><button class="btn primary" data-action="close-modal">Понятно</button></div>`);}
async function saveFile(name,type,text){if(window.AndroidBridge?.saveFile){const blob=new Blob([text],{type});const reader=new FileReader();reader.onload=()=>window.AndroidBridge.saveFile(name,type,String(reader.result).split(',')[1]);reader.readAsDataURL(blob);return;}const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function exportIcs(){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//IMPERIUM//Personal Planner//RU','CALSCALE:GREGORIAN'];for(const t of S.tasks.filter(t=>t.due_date&&t.status!=='done')){lines.push('BEGIN:VEVENT','UID:'+t.id+'@imperium','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''));if(t.due_time){const start=C.localEpoch(t.due_date,t.due_time),end=start+t.duration_minutes*60000;lines.push('DTSTART:'+new Date(start).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTEND:'+new Date(end).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''));}else lines.push('DTSTART;VALUE=DATE:'+t.due_date.replace(/-/g,''),'DTEND;VALUE=DATE:'+C.addDays(t.due_date,1).replace(/-/g,''));lines.push('SUMMARY:'+C.icsEscape(t.title),'DESCRIPTION:'+C.icsEscape(t.notes),'END:VEVENT');}lines.push('END:VCALENDAR');saveFile('IMPERIUM-calendar.ics','text/calendar;charset=utf-8',lines.join('\r\n'));}
async function action(name,id,el){switch(name){case 'new-task':return taskModal();case 'task-for-date':return taskModal(null,id);case 'edit-task':return taskModal(id);case 'new-project':return projectModal();case 'edit-project':return projectModal(id);case 'new-note':return noteModal();case 'edit-note':return noteModal(id);case 'close-modal':return closeModal();case 'add-check':$('#checklist').insertAdjacentHTML('beforeend',checkline());return;case 'remove-check':el.closest('.checkline').remove();return;case 'complete':return complete(id);case 'star':{const t=S.tasks.find(t=>t.id===id);await patchTask(t,{starred:!t.starred});await load();return;}case 'day-prev':S.date=C.addDays(S.date,-1);S.month=S.date.slice(0,7);return render();case 'day-next':S.date=C.addDays(S.date,1);S.month=S.date.slice(0,7);return render();case 'go-today':S.date=C.day();S.month=S.date.slice(0,7);return render();case 'month-prev':case 'month-next':{const d=new Date(S.month+'-15T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+(name==='month-next'?1:-1));S.month=d.toISOString().slice(0,7);return render();}case 'focus-toggle':return toggleFocus();case 'focus-reset':return resetFocus();case 'focus-preset':return resetFocus(Number(id));case 'clear-search':S.query='';return render();case 'refresh':await load();await savePendingFocus();return toast(S.offline?'Нет соединения':'Данные обновлены');case 'logout':return logout();case 'notifications':return notificationsModal();case 'enable-notifications':if(window.AndroidBridge?.requestNotificationPermission)window.AndroidBridge.requestNotificationPermission();else if('Notification'in window){const p=await Notification.requestPermission();toast(p==='granted'?'Уведомления включены, пока приложение открыто.':'Разреши уведомления в настройках браузера.');}else toast('Уведомления недоступны в этом браузере.');return;case 'exact-alarms':try{window.AndroidBridge?.requestPlannerExactAlarms?.();}catch{}return;case 'test-reminder':return notify('IMPERIUM','Пробное напоминание. Всё под контролем.');case 'download-apk':return window.location.assign('https://github.com/maestodreams-del/imperium/releases/download/v7.0.0/IMPERIUM-7.0.0.apk');case 'export-json':return saveFile('IMPERIUM-backup-'+C.day()+'.json','application/json',JSON.stringify({format:'imperium-planner',version:1,exported_at:new Date().toISOString(),tasks:S.tasks,projects:S.projects,notes:S.notes,focus_sessions:S.sessions},null,2));case 'export-ics':return exportIcs();case 'delete-task':return confirmAction('Удалить задачу?','Задача и её подзадачи будут удалены.','confirm-delete-task',id);case 'confirm-delete-task':return deleteRow('planner_tasks',id);case 'delete-note':return confirmAction('Удалить заметку?','Текст заметки будет удалён.','confirm-delete-note',id);case 'confirm-delete-note':return deleteRow('planner_notes',id);case 'archive-project':return confirmAction('Убрать проект в архив?','Задачи сохранятся в общем списке.','confirm-archive-project',id);case 'confirm-archive-project':requireOnline();await api('/rest/v1/planner_projects?id=eq.'+id,{method:'PATCH',body:{archived:true},headers:{Prefer:'return=representation'}});closeModal();S.tab='projects';return load();case 'duplicate-task':{const t=S.tasks.find(x=>x.id===id),copy={...t};for(const k of ['id','created_at','updated_at','completed_at','source_task_id'])delete copy[k];copy.title=(copy.title+' · копия').slice(0,300);copy.status='todo';copy.checklist=(copy.checklist||[]).map(x=>({...x,done:false}));const n=await insertRow('planner_tasks',copy);await load();taskModal(n.id);return;}case 'carry-overdue':return confirmAction('Перенести на сегодня?','Все незавершённые задачи с прошедшей датой получат сегодняшнюю дату. Время останется прежним.','confirm-carry','');case 'confirm-carry':requireOnline();for(const t of S.tasks.filter(t=>t.due_date&&t.due_date<C.day()&&t.status!=='done'))await patchTask(t,{due_date:C.day()});closeModal();S.date=C.day();return load();case 'more':return showModal(`${modalHead('Твоё пространство')}<div class="mobile-menu">${[...navs,['projects','Проекты'],['settings','Настройки']].map(([v,l])=>`<button data-tab="${v}">${icon(v)}${l}</button>`).join('')}</div>`);}}
let busyActions=new Set();
document.addEventListener('click',async ev=>{const el=ev.target.closest('button,a');if(!el)return;if(el.dataset.tab){S.tab=el.dataset.tab;S.query='';S.filter=S.tab==='insights'?'done':'active';if(S.tab==='today'){S.date=C.day();S.month=S.date.slice(0,7);}closeModal();render();return;}if(el.dataset.project){S.tab='project';S.project=el.dataset.project;S.query='';S.filter='active';closeModal();render();return;}if(el.dataset.date){S.date=el.dataset.date;S.month=S.date.slice(0,7);S.tab='today';S.query='';render();return;}if(el.dataset.filter){S.filter=el.dataset.filter;render();return;}if(el.dataset.action){const busyKey=el.dataset.action+':'+(el.dataset.id||'');if(busyActions.has(busyKey))return;busyActions.add(busyKey);try{await action(el.dataset.action,el.dataset.id,el);}catch(err){toast(err.message);}finally{busyActions.delete(busyKey);}}});
document.addEventListener('submit',async ev=>{if(ev.target.id!=='quick-add')return;ev.preventDefault();const input=ev.target.querySelector('input');const title=input.value.trim();if(!title)return;const b=ev.target.querySelector('button');b.disabled=true;try{await insertRow('planner_tasks',{title,due_date:S.tab==='today'?S.date:null,project_id:S.tab==='project'?S.project:null});await load();toast('Задача добавлена');}catch(err){toast(err.message);b.disabled=false;}});
document.addEventListener('change',ev=>{if(ev.target.id==='theme-setting'){S.prefs.theme=ev.target.value;write(PREF,S.prefs);applyTheme();}if(ev.target.id==='default-reminder'){S.prefs.defaultReminder=Number(ev.target.value);write(PREF,S.prefs);}if(ev.target.id==='focus-task'){S.focus.taskId=ev.target.value||null;write(FOCUS,S.focus);}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){closeModal();if(S.query){S.query='';render();}return;}if(modalRoot.innerHTML&&ev.key==='Tab'){const elems=[...modalRoot.querySelectorAll('button,input,textarea,select,a')].filter(x=>!x.disabled&&x.offsetParent!==null);if(!elems.length)return;if(ev.shiftKey&&document.activeElement===elems[0]){ev.preventDefault();elems.at(-1).focus();}else if(!ev.shiftKey&&document.activeElement===elems.at(-1)){ev.preventDefault();elems[0].focus();}return;}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(ev.key==='/'&&S.owner){ev.preventDefault();$('#search')?.parentElement.classList.add('expanded');$('#search')?.focus();}if(ev.key.toLowerCase()==='n'&&S.owner&&!ev.ctrlKey&&!ev.metaKey){ev.preventDefault();taskModal();}});
let dragged=null;document.addEventListener('dragstart',ev=>{const t=ev.target.closest('[data-drag]');if(t){dragged=t.dataset.drag;ev.dataTransfer.setData('text/plain',dragged);}});document.addEventListener('dragover',ev=>{const col=ev.target.closest('[data-drop-status]');if(col){ev.preventDefault();col.classList.add('drag-over');}});document.addEventListener('dragleave',ev=>ev.target.closest('[data-drop-status]')?.classList.remove('drag-over'));document.addEventListener('drop',async ev=>{const col=ev.target.closest('[data-drop-status]');if(!col)return;ev.preventDefault();col.classList.remove('drag-over');const t=S.tasks.find(t=>t.id===dragged);dragged=null;if(!t||t.status===col.dataset.dropStatus)return;try{if(col.dataset.dropStatus==='done')await complete(t.id);else{await patchTask(t,{status:col.dataset.dropStatus,completed_at:null});await load();}}catch(err){toast(err.message);}});
window.addEventListener('imperium-planner-resume',()=>{if(S.auth)load({quiet:true});});window.addEventListener('online',()=>{load().then(savePendingFocus);});window.addEventListener('offline',()=>{S.offline=true;if(S.owner&&!modalRoot.innerHTML)render();});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&S.auth)load({quiet:true}).then(savePendingFocus);});window.addEventListener('imperium-open-planner-task',ev=>{const id=ev.detail?.id;if(id&&S.tasks.some(t=>t.id===id))taskModal(id);});
setInterval(updateFocusDisplay,1000);setInterval(checkReminders,15000);setInterval(()=>{if(S.auth&&!document.hidden)load({quiet:true}).then(savePendingFocus);},30000);
if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol))navigator.serviceWorker.register('sw.js').catch(()=>{});
try{window.AndroidBridge?.clearAnnouncements?.();}catch{}
if(S.auth)load().then(savePendingFocus);else renderLogin();
})();
